import sys

def main():
    data = sys.stdin.read().split()
    MOD = 10**9 + 7
    n, k = int(data[0]), int(data[1])
    f = [0] * (1 << k)
    pos = 2
    for _ in range(n):
        m = int(data[pos])
        mask = 0
        for j in range(m):
            mask |= 1 << (int(data[pos + 1 + j]) - 1)
        pos += 1 + m
        f[mask] += 1
    for b in range(k):
        bit = 1 << b
        for mask in range(1 << k):
            if mask & bit:
                f[mask] += f[mask ^ bit]
    pw = [1] * (n + 1)
    for i in range(1, n + 1):
        pw[i] = pw[i - 1] * 2 % MOD
    ans = 0
    for mask in range(1 << k):
        t = pw[f[mask]]
        if (k - bin(mask).count('1')) & 1:
            ans -= t
        else:
            ans += t
    print(ans % MOD)

